<?php
require_once __DIR__ . '/../../includes/auth.php';
$id=(int)($_GET['id']??0);
$stmt=$pdo->prepare("SELECT * FROM clients WHERE id=:id LIMIT 1");$stmt->execute([':id'=>$id]);$client=$stmt->fetch(PDO::FETCH_ASSOC);
if(!$client) redirect('pages/clients/index.php');
$p=$pdo->prepare("SELECT id, project_code, project_name, status, contract_value FROM projects WHERE client_id=:id ORDER BY id DESC");$p->execute([':id'=>$id]);$projects=$p->fetchAll(PDO::FETCH_ASSOC);
$s=$pdo->prepare("SELECT id,receipt_code,sale_date,total_amount,payment_method FROM product_cashier_sales WHERE client_id=:id ORDER BY id DESC LIMIT 20");$s->execute([':id'=>$id]);$sales=$s->fetchAll(PDO::FETCH_ASSOC);
$o=$pdo->prepare("SELECT id,order_code,product_name,order_date,due_date,offered_price,down_payment,final_payment,status FROM product_custom_orders WHERE client_id=:id ORDER BY id DESC LIMIT 20");$o->execute([':id'=>$id]);$orders=$o->fetchAll(PDO::FETCH_ASSOC);
$k=$pdo->prepare("SELECT COALESCE(SUM(total_amount),0) sales_total,MAX(sale_date) last_sale FROM product_cashier_sales WHERE client_id=:id");$k->execute([':id'=>$id]);$salesKpi=$k->fetch(PDO::FETCH_ASSOC);
$k=$pdo->prepare("SELECT COUNT(*) order_total,SUM(status IN ('inquiry','approved','production')) active_total,COALESCE(SUM(GREATEST(offered_price-down_payment-final_payment,0)),0) outstanding FROM product_custom_orders WHERE client_id=:id");$k->execute([':id'=>$id]);$orderKpi=$k->fetch(PDO::FETCH_ASSOC);
$pageTitle='Detail Client - Nukari';
require_once __DIR__ . '/../../includes/header.php';require_once __DIR__ . '/../../includes/sidebar.php';
function nkr_wa_link($phone){$raw=preg_replace('/\D+/','',(string)$phone);if($raw==='')return '';if(strpos($raw,'0')===0)$raw='62'.substr($raw,1);if(strpos($raw,'62')!==0)$raw='62'.$raw;return 'https://wa.me/'.$raw;}
?>
<main class="main-content">
<div class="page-header d-flex justify-content-between align-items-center"><div><h1 class="fw-bold mb-1"><?= htmlspecialchars($client['client_name']); ?></h1><p class="text-muted mb-0">Profil terpadu, project, transaksi POS, dan custom order.</p></div><a class="btn btn-outline-secondary" href="<?= base_url('pages/clients/index.php'); ?>">Kembali</a></div>
<div class="row g-3 mb-3"><div class="col-md-3"><div class="panel h-100"><div class="text-muted small">Nilai POS</div><h5 class="mb-0"><?= rupiah($salesKpi['sales_total']); ?></h5></div></div><div class="col-md-3"><div class="panel h-100"><div class="text-muted small">Custom Order</div><h5 class="mb-0"><?= (int)$orderKpi['order_total']; ?></h5></div></div><div class="col-md-3"><div class="panel h-100"><div class="text-muted small">Order Aktif</div><h5 class="mb-0"><?= (int)$orderKpi['active_total']; ?></h5></div></div><div class="col-md-3"><div class="panel h-100"><div class="text-muted small">Sisa Tagihan</div><h5 class="mb-0"><?= rupiah($orderKpi['outstanding']); ?></h5></div></div></div>
<div class="row g-3"><div class="col-lg-4"><div class="panel"><h5 class="fw-bold">Informasi Client</h5><p><strong>PIC:</strong><br><?= htmlspecialchars($client['contact_person'] ?: '-'); ?><br><small><?= htmlspecialchars($client['contact_position'] ?? ''); ?></small></p><p><strong>Kontak:</strong><br><?php if($client['phone']): ?><a target="_blank" href="<?= nkr_wa_link($client['phone']); ?>"><?= htmlspecialchars($client['phone']); ?></a><br><?php endif; ?><?php if($client['email']): ?><a href="mailto:<?= htmlspecialchars($client['email']); ?>"><?= htmlspecialchars($client['email']); ?></a><?php endif; ?></p><p><strong>Alamat:</strong><br><?= nl2br(htmlspecialchars($client['address'] ?: '-')); ?></p><p><strong>Catatan:</strong><br><?= nl2br(htmlspecialchars($client['notes'] ?: '-')); ?></p></div></div>
<div class="col-lg-8"><div class="panel"><h5 class="fw-bold">Riwayat Project</h5><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Kode</th><th>Project</th><th>Status</th><th>Nilai</th><th></th></tr></thead><tbody><?php foreach($projects as $pr): ?><tr><td><?= htmlspecialchars($pr['project_code'] ?: '-'); ?></td><td><?= htmlspecialchars($pr['project_name']); ?></td><td><?= htmlspecialchars($pr['status']); ?></td><td><?= rupiah($pr['contract_value']); ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= base_url('pages/projects/detail.php?id='.(int)$pr['id']); ?>">Buka</a></td></tr><?php endforeach; if(!$projects): ?><tr><td colspan="5" class="text-center text-muted">Belum ada project.</td></tr><?php endif; ?></tbody></table></div></div></div></div>
<div class="row g-3 mt-1"><div class="col-lg-6"><div class="panel h-100"><h5 class="fw-bold">Riwayat POS</h5><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Tanggal</th><th>Struk</th><th class="text-end">Nilai</th><th></th></tr></thead><tbody><?php foreach($sales as $sale): ?><tr><td><?= htmlspecialchars($sale['sale_date']); ?></td><td><?= htmlspecialchars($sale['receipt_code']); ?></td><td class="text-end"><?= rupiah($sale['total_amount']); ?></td><td><a class="btn btn-sm btn-outline-success" href="<?= base_url('pages/products/cashier_receipt.php?type=sale&id='.(int)$sale['id']); ?>">Detail</a></td></tr><?php endforeach; if(!$sales): ?><tr><td colspan="4" class="text-center text-muted">Belum ada transaksi POS.</td></tr><?php endif; ?></tbody></table></div></div></div>
<div class="col-lg-6"><div class="panel h-100"><h5 class="fw-bold">Riwayat Custom Order</h5><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Order</th><th>Produk</th><th>Status</th><th class="text-end">Sisa</th><th></th></tr></thead><tbody><?php foreach($orders as $order): $balance=max(0,(float)$order['offered_price']-(float)$order['down_payment']-(float)$order['final_payment']); ?><tr><td><?= htmlspecialchars($order['order_code']); ?><div class="small text-muted"><?= htmlspecialchars($order['order_date']); ?></div></td><td><?= htmlspecialchars($order['product_name']); ?></td><td><?= htmlspecialchars(ucwords($order['status'])); ?></td><td class="text-end"><?= rupiah($balance); ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= base_url('pages/products/custom_orders.php?detail='.(int)$order['id']); ?>">Detail</a></td></tr><?php endforeach; if(!$orders): ?><tr><td colspan="5" class="text-center text-muted">Belum ada custom order.</td></tr><?php endif; ?></tbody></table></div></div></div></div>
</main><?php require_once __DIR__ . '/../../includes/footer.php'; ?>
